#!/usr/bin/env python3
"""
Test the core fix for client_id in scopes without reserved scope conflicts.
"""

from msal import PublicClientApplication

def test_core_fix():
    """Test the core fix without reserved scope interference."""
    print("=== Testing Core Fix ===")

    client_id = "test-client_id_12345"
    app = PublicClientApplication(client_id=client_id, authority="https://login.microsoftonline.com/common")

    # This is the core issue: client_id with non-reserved scopes
    print("\n1. Core issue test: [client_id, 'custom.scope']")
    try:
        scopes = [client_id, 'custom.scope']
        result = app._decorate_scope(scopes)
        print(f"   ✓ SUCCESS! Result: {sorted(result)}")
        # Check that both client_id and reserved scopes are present
        if client_id in result and 'openid' in result and 'offline_access' in result:
            print("   ✓ Contains client_id and reserved scopes - perfect for Azure B2C!")
        else:
            print("   ✗ Missing expected elements")
    except Exception as e:
        print(f"   ✗ FAILED: {e}")

    # Test backward compatibility: client_id alone
    print("\n2. Backward compatibility: [client_id]")  
    try:
        scopes = [client_id]
        result = app._decorate_scope(scopes)
        print(f"   ✓ SUCCESS! Result: {sorted(result)}")
        # Should NOT contain client_id, should contain only reserved scopes
        if client_id not in result and set(['openid', 'profile', 'offline_access']).issubset(set(result)):
            print("   ✓ Correctly replaced client_id with reserved scopes")
        else:
            print("   ✗ Unexpected result for single client_id")
    except Exception as e:
        print(f"   ✗ FAILED: {e}")

    # Test normal case
    print("\n3. Normal case: ['custom.scope']")
    try:
        scopes = ['custom.scope']
        result = app._decorate_scope(scopes)
        print(f"   ✓ SUCCESS! Result: {sorted(result)}")
        if 'custom.scope' in result and set(['openid', 'profile', 'offline_access']).issubset(set(result)):
            print("   ✓ Correctly added reserved scopes to custom scope")
        else:
            print("   ✗ Unexpected result for custom scope")
    except Exception as e:
        print(f"   ✗ FAILED: {e}")

if __name__ == "__main__":
    test_core_fix()

