"""
Test edge cases for the _decorate_scope fix.
"""

from msal import PublicClientApplication

def test_edge_cases():
    """Test edge cases to ensure robustness."""
    print("=== Edge Case Testing ===")

    client_id = "test-app-12345"
    app = PublicClientApplication(client_id=client_id, authority="https://login.microsoftonline.com/common")

    edge_cases = [
        # Description, input, should_succeed, expected_characteristics
        ("Empty list", [], True, lambda r: set(['openid', 'profile', 'offline_access']).issubset(set(r))),
        ("Duplicate scopes", [client_id, 'custom.scope', client_id], True, lambda r: len([x for x in r if x == client_id]) == 1),
        ("Client ID multiple times", [client_id, client_id, client_id], True, lambda r: client_id not in r and len(r) == 3),  # Should be treated as single client_id
        ("None as scope (should fail)", None, False, None),
        ("String instead of list (should fail)", "scope", False, None),
        ("Tuple input", (client_id, 'custom.scope'), True, lambda r: client_id in r and 'custom.scope' in r),
        ("Set input", {client_id, 'custom.scope'}, True, lambda r: client_id in r and 'custom.scope' in r),
    ]

    for i, (description, input_scopes, should_succeed, expected_check) in enumerate(edge_cases, 1):
        print(f"\n{i}. {description}")
        print(f"   Input: {input_scopes}")
        try:
            result = app._decorate_scope(input_scopes)
            if should_succeed:
                print(f"   ✓ Success: {sorted(result)}")
                if expected_check:
                    if expected_check(result):
                        print("   ✓ Meets expected characteristics")
                    else:
                        print("   ✗ Does not meet expected characteristics")
            else:
                print(f"   ✗ Unexpected success: {sorted(result)}")
        except Exception as e:
            if not should_succeed:
                print(f"   ✓ Expected failure: {type(e).__name__}: {e}")
            else:
                print(f"   ✗ Unexpected failure: {type(e).__name__}: {e}")

    # Test the specific edge case: what happens when client_id is provided multiple times
    print(f"\n=== Specific Edge Case: Duplicate Client IDs ===")
    print("Input: [client_id, 'scope1', client_id, 'scope2', client_id]")
    try:
        scopes = [client_id, 'scope1', client_id, 'scope2', client_id]
        result = app._decorate_scope(scopes)
        print(f"Result: {sorted(result)}")
        print(f"Length: {len(result)} (duplicates removed)")
        if client_id in result:
            print("✓ Contains client_id as expected for Azure B2C")
        else:
            print("✗ Missing client_id")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    test_edge_cases()
